mapper.update:
UPDATE diary
SET content = #{content},
    last_modified_at = #{lastModifiedAt},
    modify_count = #{modifyCount},
    is_pinned = #{isPinned}
WHERE id = #{id}

mapper.select:
SELECT id, LEFT(content, 30) AS content_preview, created_at, last_modified_at, modify_count, first_weather, is_pinned, diary_date FROM diary WHERE diary_date = #{date}
ORDER BY is_pinned DESC, last_modified_at DESC
ORDER BY is_pinned DESC, created_at DESC
